CREATE OR REPLACE FUNCTION public.respond_owner_review(_review_id uuid, _expected_updated_at timestamp with time zone, _decision text, _response text, _owner_update_revision integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE review public.owner_reviews; program public.owner_programs; snapshot jsonb;
BEGIN
 -- Scope validation locks program then review before any response write.
 snapshot:=public.read_owner_review_update(_review_id,_owner_update_revision);
 SELECT p.* INTO program FROM public.owner_programs p JOIN public.owner_reviews r ON r.program_id=p.id WHERE r.id=_review_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT coalesce(private.is_program_member(program.id,auth.uid()),false) OR program.archived_at IS NOT NULL OR program.status IN ('closed','completed') THEN
  RAISE EXCEPTION 'This participation program is not available for your response.';
 END IF;
 SELECT * INTO review FROM public.owner_reviews WHERE id=_review_id AND program_id=program.id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'This opportunity is not available.'; END IF;
 IF _expected_updated_at IS NULL OR review.updated_at IS DISTINCT FROM _expected_updated_at THEN RAISE EXCEPTION 'The opportunity changed. Refresh before responding.'; END IF;
 IF review.status NOT IN ('awaiting_owner','returned') OR review.available_from>now() THEN RAISE EXCEPTION 'This opportunity is not currently awaiting your response.'; END IF;
 IF length(trim(coalesce(_decision,''))) NOT BETWEEN 1 AND 60 OR length(coalesce(_response,''))>2000 THEN RAISE EXCEPTION 'Enter a valid response.'; END IF;
 IF review.auto_ticket AND _decision<>'acknowledged' THEN RAISE EXCEPTION 'Use the canonical approval request; this response records participation only.'; END IF;

 UPDATE public.owner_reviews SET owner_decision=_decision,owner_response=nullif(_response,''),
  status=CASE WHEN auto_ticket THEN status ELSE 'answered' END,responded_at=now(),updated_at=clock_timestamp() WHERE id=review.id;
 INSERT INTO public.owner_program_events(program_id,review_id,kind,summary,actor_id,previous_value,new_value,detail)
 VALUES(review.program_id,review.id,CASE WHEN review.auto_ticket THEN 'owner_participation_response' ELSE 'owner_decision' END,
  CASE WHEN review.auto_ticket THEN 'Participation response recorded for property work; no repair approval granted.' ELSE 'Owner response recorded for participation opportunity.' END,
  auth.uid(),review.owner_decision,_decision,jsonb_build_object('previousResponse',review.owner_response,'response',nullif(_response,''),'ownerUpdate',snapshot,'propertyId',review.property_id,'ticketId',review.ticket_id));
 RETURN review.id;
END $function$

CREATE OR REPLACE FUNCTION public.ao_submit_card(_plan_card uuid, _values jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE pc public.ao_home_plan_cards; cid uuid; uid uuid := auth.uid(); sib public.ao_home_plan_cards;
BEGIN
  SELECT * INTO pc FROM public.ao_home_plan_cards WHERE id = _plan_card FOR UPDATE;
  IF NOT FOUND OR uid IS NULL
     OR NOT private.owner_current_property_for_actor(uid, pc.property_id, pc.program_id) THEN
    RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501';
  END IF;
  IF pc.unlocked_at IS NULL THEN RAISE EXCEPTION 'This item is not open yet'; END IF;
  IF pc.expired_at IS NOT NULL THEN RAISE EXCEPTION 'This item has closed'; END IF;
  IF pc.owner_completed_at IS NOT NULL THEN RAISE EXCEPTION 'Another homeowner already answered this item'; END IF;
  INSERT INTO public.ao_contributions(plan_card_id, property_id, program_id, card_id, submitted_by, field_values)
    VALUES (pc.id, pc.property_id, pc.program_id, pc.card_id, uid, coalesce(_values, '{}'::jsonb)) RETURNING id INTO cid;
  UPDATE public.ao_home_plan_cards SET owner_completed_at = now() WHERE id = pc.id;
  UPDATE public.owner_reviews SET status = 'answered', responded_at = now(), updated_at = now() WHERE id = pc.owner_review_id;
  IF EXISTS (SELECT 1 FROM public.ao_library_cards c WHERE c.id = pc.card_id AND c.once_per_owner) THEN
    FOR sib IN SELECT * FROM public.ao_home_plan_cards s
               WHERE s.program_id = pc.program_id AND s.card_id = pc.card_id AND s.id <> pc.id
                 AND s.unlocked_at IS NOT NULL AND s.expired_at IS NULL AND s.owner_completed_at IS NULL
               FOR UPDATE LOOP
      CONTINUE WHEN NOT private.owner_current_property_for_actor(uid, sib.property_id, sib.program_id);
      INSERT INTO public.ao_contributions(plan_card_id, property_id, program_id, card_id, submitted_by, field_values)
        VALUES (sib.id, sib.property_id, sib.program_id, sib.card_id, uid, coalesce(_values, '{}'::jsonb));
      UPDATE public.ao_home_plan_cards SET owner_completed_at = now() WHERE id = sib.id;
      UPDATE public.owner_reviews SET status = 'answered', responded_at = now(), updated_at = now() WHERE id = sib.owner_review_id;
    END LOOP;
  END IF;
  RETURN cid;
END $function$

CREATE OR REPLACE FUNCTION public.ao_submit_card(_plan_card uuid, _values jsonb, _files jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); pc public.ao_home_plan_cards; f jsonb; new_files jsonb := coalesce(_files, '[]'::jsonb); cid uuid;
BEGIN
  IF jsonb_typeof(new_files) <> 'array' OR jsonb_array_length(new_files) > 20 THEN RAISE EXCEPTION 'Attach up to 20 files.'; END IF;
  SELECT * INTO pc FROM public.ao_home_plan_cards WHERE id = _plan_card;
  IF NOT FOUND OR uid IS NULL OR NOT private.owner_current_property_for_actor(uid, pc.property_id, pc.program_id) THEN
    RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501';
  END IF;
  FOR f IN SELECT * FROM jsonb_array_elements(new_files) LOOP
    IF NOT EXISTS (SELECT 1 FROM public.documents d WHERE d.id = (f ->> 'document_id')::uuid AND d.deleted_at IS NULL
                     AND (d.property_id = pc.property_id OR (d.entity_type = 'property' AND d.entity_id = pc.property_id))
                     AND d.uploaded_by = uid) THEN
      RAISE EXCEPTION 'A file is not one of your files on this home.';
    END IF;
  END LOOP;
  new_files := coalesce((SELECT jsonb_agg(jsonb_build_object('document_id', x ->> 'document_id', 'name', left(coalesce(x ->> 'name', ''), 300)))
                       FROM jsonb_array_elements(new_files) x), '[]'::jsonb);
  cid := public.ao_submit_card(_plan_card, _values);
  IF jsonb_array_length(new_files) > 0 THEN
    UPDATE public.ao_contributions x SET files = new_files
     WHERE x.id = cid
        OR (x.program_id = pc.program_id AND x.card_id = pc.card_id AND x.submitted_by = uid AND x.submitted_at = now());
  END IF;
  RETURN cid;
END $function$

CREATE OR REPLACE FUNCTION public.respond_owner_opportunity(_id uuid, _kind text, _decision text, _text text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE w record; t record; _appr uuid; _result text := null; _owner text; _note text;
BEGIN
  SELECT wi.* INTO w FROM work_items wi JOIN owner_programs p ON p.id=wi.program_id
   WHERE wi.id=_id AND wi.kind='opportunity' AND wi.status NOT IN ('draft','archived') AND private.is_program_member(p.id,auth.uid())
   FOR UPDATE OF wi;
  IF w IS NULL THEN RAISE EXCEPTION 'This Opportunity is not available to you.'; END IF;
  IF _kind NOT IN ('acknowledge','feedback','decision') OR NOT (_kind = ANY (w.response_types)) THEN
    RAISE EXCEPTION 'This Opportunity does not take that kind of response.'; END IF;
  IF _kind='feedback' AND coalesce(trim(_text),'')='' THEN RAISE EXCEPTION 'Type your feedback before submitting.'; END IF;
  IF _kind='decision' AND coalesce(_decision,'') NOT IN ('authorize','changes') THEN RAISE EXCEPTION 'Choose a decision.'; END IF;
  IF length(coalesce(_text,'')) > 5000 THEN RAISE EXCEPTION 'Please keep your response under 5,000 characters.'; END IF;
  SELECT coalesce(pr.full_name,'The homeowner') INTO _owner FROM profiles pr WHERE pr.id=auth.uid();
  _owner := coalesce(_owner,'The homeowner');
  IF _kind='decision' AND w.source='arha' AND w.source_task_id IS NOT NULL THEN
    SELECT * INTO t FROM onboarding_tasks WHERE id=w.source_task_id AND property_id=w.property_id AND archived_at IS NULL FOR UPDATE;
    IF t.id IS NOT NULL AND (coalesce(t.requires_owner_approval,false) OR coalesce(t.owner_dependency,'')='business_decision') AND t.owner_approval_status='approved' THEN
      RAISE EXCEPTION 'This decision was already answered by an owner on this program.';
    END IF;
    IF t.id IS NOT NULL AND (coalesce(t.requires_owner_approval,false) OR coalesce(t.owner_dependency,'')='business_decision') AND t.owner_approval_status IN ('awaiting_owner','changes_requested','pending','not_required') THEN
      SELECT id INTO _appr FROM approvals WHERE entity_type='onboarding_task' AND entity_id=t.id AND property_id=t.property_id AND status IN ('pending','awaiting_owner') ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
      _note := _owner||' '||CASE WHEN _decision='authorize' THEN 'authorized this work' ELSE 'requested changes' END
               ||' in Opportunity "'||w.title||'"'||coalesce(': '||nullif(trim(coalesce(_text,'')),''),'');
      IF _decision='authorize' THEN
        IF _appr IS NOT NULL THEN
          UPDATE approvals SET status='approved', decision_note=_note, decided_at=now(), responded_at=now(), response_channel='owner_portal' WHERE id=_appr;
        END IF;
        UPDATE onboarding_tasks SET owner_approval_status='approved' WHERE id=t.id;
        INSERT INTO audit_log(actor_id, action, entity_type, entity_id, entity_label, after_value)
          VALUES (auth.uid(), 'owner_item_approved', 'onboarding_task', t.id, t.title, jsonb_build_object('opportunity', w.id, 'at', now()));
        _result := 'approved';
      ELSE
        IF _appr IS NOT NULL THEN UPDATE approvals SET decision_note=_note WHERE id=_appr; END IF;
        _result := 'still_waiting';
      END IF;
    END IF;
  END IF;
  UPDATE work_items SET responded_at=now(), viewed_at=coalesce(viewed_at, now()),
    owner_response = owner_response || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'kind',_kind,'decision',_decision,'text',nullif(trim(coalesce(_text,'')),''),'at',now(),
      'by',_owner,'task_id',CASE WHEN _result IS NOT NULL THEN w.source_task_id END,'task_approval',_result)))
   WHERE id=_id;
  PERFORM private.notify_opportunity_staff(_id, CASE WHEN _kind<>'decision' THEN 'responded'
    WHEN _decision='authorize' THEN 'authorized this work' ELSE 'requested changes' END);
END $function$

CREATE OR REPLACE FUNCTION public.ao_edit_card_answer(_plan_card uuid, _values jsonb, _files jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); pc public.ao_home_plan_cards; c public.ao_library_cards; con public.ao_contributions;
  f jsonb; new_files jsonb := coalesce(_files, '[]'::jsonb); vals jsonb := coalesce(_values, '{}'::jsonb);
  change_id uuid; mid uuid; sib public.ao_home_plan_cards;
BEGIN
  SELECT * INTO pc FROM public.ao_home_plan_cards WHERE id = _plan_card FOR UPDATE;
  IF NOT FOUND OR uid IS NULL OR NOT private.owner_current_property_for_actor(uid, pc.property_id, pc.program_id) THEN
    RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501';
  END IF;
  IF pc.owner_completed_at IS NULL THEN RAISE EXCEPTION 'Send your answer first.'; END IF;
  IF jsonb_typeof(vals) <> 'object' THEN RAISE EXCEPTION 'Your answer could not be read.'; END IF;
  IF jsonb_typeof(new_files) <> 'array' OR jsonb_array_length(new_files) > 20 THEN RAISE EXCEPTION 'Attach up to 20 files.'; END IF;
  SELECT * INTO c FROM public.ao_library_cards WHERE id = pc.card_id;
  SELECT * INTO con FROM public.ao_contributions WHERE plan_card_id = pc.id ORDER BY submitted_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    -- Finished with nothing saved: her first answer starts the record (an empty before in history).
    IF vals = '{}'::jsonb AND jsonb_array_length(new_files) = 0 THEN RAISE EXCEPTION 'Write your answer or add a file first.'; END IF;
    INSERT INTO public.ao_contributions(plan_card_id, property_id, program_id, card_id, submitted_by, field_values, files)
      VALUES (pc.id, pc.property_id, pc.program_id, pc.card_id, uid, '{}'::jsonb, '[]'::jsonb)
      RETURNING * INTO con;
  END IF;
  FOR f IN SELECT * FROM jsonb_array_elements(new_files) LOOP
    IF NOT EXISTS (SELECT 1 FROM public.documents d WHERE d.id = (f ->> 'document_id')::uuid AND d.deleted_at IS NULL
                     AND (d.property_id = pc.property_id OR (d.entity_type = 'property' AND d.entity_id = pc.property_id))
                     AND (d.uploaded_by = uid OR con.files @> jsonb_build_array(jsonb_build_object('document_id', f ->> 'document_id')))) THEN
      RAISE EXCEPTION 'A file is not one of your files on this home.';
    END IF;
  END LOOP;
  new_files := coalesce((SELECT jsonb_agg(jsonb_build_object('document_id', x ->> 'document_id', 'name', left(coalesce(x ->> 'name', ''), 300)))
                       FROM jsonb_array_elements(new_files) x), '[]'::jsonb);
  IF con.field_values = vals AND con.files = new_files THEN RAISE EXCEPTION 'Nothing changed.'; END IF;
  mid := public.post_home_chat_message(pc.property_id, 'owner', 'I updated my answer on ' || c.title || '.', '[]'::jsonb, '{}'::uuid[]);
  INSERT INTO public.ao_contribution_changes(plan_card_id, contribution_id, property_id, program_id, changed_by,
      before_values, after_values, before_files, after_files, chat_message_id)
    VALUES (pc.id, con.id, pc.property_id, pc.program_id, uid, con.field_values, vals, con.files, new_files, mid)
    RETURNING id INTO change_id;
  UPDATE public.ao_contributions SET field_values = vals, files = new_files WHERE id = con.id;
  PERFORM private.record_homeowner_update(pc.program_id, pc.property_id, 'card', pc.id, c.title, pc.linked_task_id,
    'Homeowner updated the answer on ' || c.title, NULL, mid);
  -- A market card answered once for every home keeps one answer: its other homes' copies follow.
  IF c.once_per_owner THEN
    FOR sib IN SELECT * FROM public.ao_home_plan_cards s
                WHERE s.program_id = pc.program_id AND s.card_id = pc.card_id AND s.id <> pc.id AND s.owner_completed_at IS NOT NULL LOOP
      CONTINUE WHEN NOT private.owner_current_property_for_actor(uid, sib.property_id, sib.program_id);
      INSERT INTO public.ao_contribution_changes(plan_card_id, contribution_id, property_id, program_id, changed_by,
          before_values, after_values, before_files, after_files, chat_message_id)
        SELECT sib.id, x.id, sib.property_id, sib.program_id, uid, x.field_values, vals, x.files, new_files, mid
          FROM public.ao_contributions x WHERE x.plan_card_id = sib.id ORDER BY x.submitted_at DESC LIMIT 1;
      UPDATE public.ao_contributions SET field_values = vals, files = new_files
       WHERE id = (SELECT x.id FROM public.ao_contributions x WHERE x.plan_card_id = sib.id ORDER BY x.submitted_at DESC LIMIT 1);
    END LOOP;
  END IF;
  RETURN change_id;
END $function$

CREATE OR REPLACE FUNCTION public.log_owner_time_entry(_entry jsonb, _property_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE program public.owner_programs; opportunity public.owner_reviews; enrollment public.owner_program_properties;
 home public.properties; link record; chosen uuid[]; context_ids uuid[]; chosen_property uuid;
 entry_day date; reported_minutes integer; new_id uuid; ticket public.tickets; manual boolean;
 paths jsonb; path_item text;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to record participation.'; END IF;
 IF _entry IS NULL OR jsonb_typeof(_entry) IS DISTINCT FROM 'object' OR (_entry->'confirmed') IS DISTINCT FROM 'true'::jsonb THEN
  RAISE EXCEPTION 'Confirm that this entry records the time you personally spent.';
 END IF;
 program:=private.lock_owner_time_program((_entry->>'programId')::uuid,auth.uid(),false,true);
 entry_day:=(_entry->>'entryDate')::date; reported_minutes:=(_entry->>'minutes')::integer;
 manual:=nullif(_entry->>'reviewId','') IS NULL;
 IF entry_day IS NULL OR NOT isfinite(entry_day) OR entry_day>private.business_today() THEN
  RAISE EXCEPTION 'Choose a date no later than today.';
 END IF;
 IF length(trim(coalesce(_entry->>'activity',''))) < 3 THEN
  RAISE EXCEPTION 'What did you do? needs at least 3 characters.';
 END IF;
 IF length(trim(coalesce(_entry->>'activity',''))) > 2000 THEN
  RAISE EXCEPTION 'What did you do? can be up to 2,000 characters.';
 END IF;
 IF reported_minutes IS NULL OR reported_minutes NOT BETWEEN 1 AND 1440 THEN
  RAISE EXCEPTION 'Minutes spent must be a whole number from 1 to 1,440.';
 END IF;
 IF length(coalesce(_entry->>'output',''))>1000 OR length(coalesce(_entry->>'comments',''))>1000 THEN
  RAISE EXCEPTION 'Notes can be up to 1,000 characters.';
 END IF;
 IF coalesce(_entry->>'phase','') NOT IN ('onboarding','ongoing')
  OR length(coalesce(_entry->>'activityCategory',''))>80 OR length(coalesce(_entry->>'output',''))>1000
  OR length(coalesce(_entry->>'comments',''))>1000 OR length(coalesce(_entry->>'attachmentPath',''))>400 THEN
   RAISE EXCEPTION 'This could not save. Your entry is still here. Please try again, and if it happens again, message your ARHA contact.';
 END IF;
 paths:=coalesce(_entry->'attachmentPaths','[]'::jsonb);
 IF jsonb_typeof(paths) IS DISTINCT FROM 'array' OR jsonb_array_length(paths)>10 THEN
  RAISE EXCEPTION 'Attach at most ten files to one entry.';
 END IF;
 FOR path_item IN SELECT jsonb_array_elements_text(paths) LOOP
  IF path_item IS NULL OR length(trim(path_item)) NOT BETWEEN 1 AND 400 THEN
   RAISE EXCEPTION 'One of the attached files could not be recorded. Try again.';
   END IF;
 END LOOP;
 IF jsonb_array_length(paths)>0 AND nullif(_entry->>'attachmentPath','') IS DISTINCT FROM (paths->>0) THEN
  RAISE EXCEPTION 'The attached files could not be recorded. Try again.';
 END IF;
 IF cardinality(coalesce(_property_ids,'{}'::uuid[]))>25 OR array_position(_property_ids,NULL) IS NOT NULL THEN
  RAISE EXCEPTION 'Choose at most 25 valid properties.';
 END IF;
 SELECT coalesce(array_agg(DISTINCT p ORDER BY p),'{}'::uuid[]) INTO chosen FROM unnest(coalesce(_property_ids,'{}'::uuid[])) p;
 IF manual THEN
   IF nullif(_entry->>'ticketId','') IS NOT NULL THEN
   RAISE EXCEPTION 'A self-recorded activity cannot carry a Ticket link.';
   END IF;
  context_ids:=chosen;
 ELSE
  SELECT * INTO opportunity FROM public.owner_reviews WHERE id=(_entry->>'reviewId')::uuid AND program_id=program.id FOR SHARE NOWAIT;
  IF NOT FOUND OR opportunity.archived_at IS NOT NULL OR opportunity.is_demo IS DISTINCT FROM program.is_demo
   OR coalesce(opportunity.status,'') NOT IN ('awaiting_owner','answered','returned') OR opportunity.available_from>now() OR opportunity.available_from::date>entry_day
   OR opportunity.phase IS DISTINCT FROM (_entry->>'phase') THEN
   RAISE EXCEPTION 'Choose an available participation opportunity from this program.';
   END IF;
  IF opportunity.task_type NOT IN ('property_specific','multi_property','program_wide') OR opportunity.task_type IS NULL THEN
   RAISE EXCEPTION 'This opportunity needs a valid participation scope.';
  END IF;
  IF opportunity.task_type='property_specific' THEN
   IF opportunity.property_id IS NULL THEN RAISE EXCEPTION 'This opportunity needs its canonical Property.'; END IF;
   IF cardinality(chosen)=0 THEN chosen:=ARRAY[opportunity.property_id]; END IF;
   IF chosen IS DISTINCT FROM ARRAY[opportunity.property_id] THEN RAISE EXCEPTION 'That opportunity belongs to a different Property.'; END IF;
  ELSIF opportunity.task_type='multi_property' AND cardinality(chosen)=0 THEN
   RAISE EXCEPTION 'Select the opportunity properties this activity involved.';
   ELSIF opportunity.task_type='program_wide' AND opportunity.property_id IS NOT NULL THEN
   RAISE EXCEPTION 'The program-wide opportunity has conflicting Property context.';
   END IF;
  context_ids:=chosen;
  IF opportunity.property_id IS NOT NULL THEN context_ids:=array_append(context_ids,opportunity.property_id); END IF;
  FOR link IN SELECT r.property_id FROM public.owner_review_properties r WHERE r.review_id=opportunity.id ORDER BY r.property_id FOR SHARE NOWAIT LOOP
   context_ids:=array_append(context_ids,link.property_id);
   IF opportunity.task_type='property_specific' AND link.property_id IS DISTINCT FROM opportunity.property_id THEN
    RAISE EXCEPTION 'The opportunity Property links changed. Ask the team to reconcile them.';
   END IF;
   END LOOP;
  IF opportunity.task_type='multi_property' AND EXISTS(SELECT 1 FROM unnest(chosen) p WHERE NOT EXISTS(
   SELECT 1 FROM public.owner_review_properties r WHERE r.review_id=opportunity.id AND r.property_id=p
  )) THEN RAISE EXCEPTION 'That Property is not assigned to this participation opportunity.'; END IF;
 END IF;
 FOR chosen_property IN SELECT DISTINCT p FROM unnest(context_ids) p ORDER BY p LOOP
  SELECT * INTO enrollment FROM public.owner_program_properties e WHERE e.program_id=program.id AND e.property_id=chosen_property FOR SHARE NOWAIT;
  IF NOT FOUND OR enrollment.inclusion_status IS DISTINCT FROM 'included' OR enrollment.archived_at IS NOT NULL
   OR enrollment.is_demo IS DISTINCT FROM program.is_demo THEN
   RAISE EXCEPTION 'Tag only homes included in this program.';
   END IF;
  SELECT * INTO home FROM public.properties h WHERE h.id=chosen_property FOR SHARE NOWAIT;
  IF NOT FOUND OR home.owner_record_id IS DISTINCT FROM program.owner_record_id OR home.archived_at IS NOT NULL
   OR home.is_demo IS DISTINCT FROM program.is_demo THEN RAISE EXCEPTION 'That Property is no longer available to this Owner.'; END IF;
 END LOOP;
 IF NOT manual THEN
  IF nullif(_entry->>'ticketId','')::uuid IS DISTINCT FROM opportunity.ticket_id THEN
   RAISE EXCEPTION 'Time must retain its participation opportunity Ticket link.';
  END IF;
  IF opportunity.ticket_id IS NOT NULL THEN
    SELECT * INTO ticket FROM public.tickets WHERE id=opportunity.ticket_id FOR SHARE NOWAIT;
   IF NOT FOUND OR ticket.property_id IS DISTINCT FROM opportunity.property_id OR NOT ticket.property_id=ANY(chosen)
    OR ticket.is_demo IS DISTINCT FROM program.is_demo THEN RAISE EXCEPTION 'The opportunity Ticket context changed.'; END IF;
  END IF;
 END IF;
 -- Double save guard (Nov 21): the same homeowner, program, date, minutes and description saved in the
 -- last 10 minutes is already on file.
 IF private.owner_time_recent_repeat(program.id,auth.uid(),entry_day,reported_minutes,trim(_entry->>'activity'),NULL,NULL) THEN
  RAISE EXCEPTION 'Already saved.';
 END IF;
 INSERT INTO public.owner_time_entries(program_id,owner_user_id,phase,entry_date,minutes,activity,activity_category,decision_outcome,output,comments,attachment_path,attachment_paths,review_id,ticket_id,attested,is_demo,owner_update_revision,review_status)
 VALUES(program.id,auth.uid(),_entry->>'phase',entry_day,reported_minutes,trim(_entry->>'activity'),nullif(_entry->>'activityCategory',''),nullif(_entry->>'output',''),nullif(_entry->>'output',''),nullif(_entry->>'comments',''),nullif(_entry->>'attachmentPath',''),paths,opportunity.id,opportunity.ticket_id,true,program.is_demo,
  CASE WHEN manual THEN NULL ELSE nullif(_entry->>'ownerUpdateRevision','')::integer END,'submitted')
 RETURNING id INTO new_id;
 INSERT INTO public.owner_time_entry_properties(entry_id,property_id) SELECT new_id,p FROM unnest(chosen) p;
  UPDATE public.owner_program_properties e SET last_owner_activity_at=now() WHERE e.program_id=program.id AND e.property_id=ANY(chosen);
 UPDATE public.owner_programs SET last_owner_activity_at=now() WHERE id=program.id;
 INSERT INTO public.owner_program_events(program_id,entry_id,review_id,kind,summary,actor_id,new_value,detail)
 VALUES(program.id,new_id,opportunity.id,'time_entry',reported_minutes::text||' minutes reported: '||trim(_entry->>'activity'),auth.uid(),reported_minutes::text,
  jsonb_build_object('propertyIds',to_jsonb(chosen),'phase',_entry->>'phase','category',_entry->>'activityCategory','selfRecorded',manual,'attachmentCount',jsonb_array_length(paths)));
 RETURN new_id;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'The program or opportunity is being updated. Refresh and try again.';
END $function$

CREATE OR REPLACE FUNCTION public.owner_update_time_entry(_entry_id uuid, _change jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); original public.owner_time_entries; program public.owner_programs; review public.owner_reviews;
  scope uuid; new_id uuid; mode text; act text; day date; mins integer; note text; paths jsonb; old_paths jsonb; added jsonb; p text;
  comments text; reason text; changed text[] := '{}'; label text; home uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Sign in to change your hours.'; END IF;
  IF _change IS NULL OR jsonb_typeof(_change) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Your change could not be read. Try again.'; END IF;
  mode := coalesce(_change->>'mode', 'edit');
  IF mode NOT IN ('edit', 'add') THEN RAISE EXCEPTION 'Your change could not be read. Try again.'; END IF;
  SELECT program_id INTO scope FROM public.owner_time_entries WHERE id = _entry_id AND owner_user_id = uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'That entry is not available to you.'; END IF;
  program := private.lock_owner_time_program(scope, uid, false, false);
  IF NOT pg_try_advisory_xact_lock(hashtextextended('owner-time-correction:' || _entry_id::text, 0)) THEN
    RAISE EXCEPTION 'This entry is being changed. Refresh and try again.';
  END IF;
  SELECT * INTO original FROM public.owner_time_entries WHERE id = _entry_id FOR UPDATE NOWAIT;
  IF NOT FOUND OR original.program_id IS DISTINCT FROM program.id OR original.owner_user_id IS DISTINCT FROM uid
     OR original.is_demo IS DISTINCT FROM program.is_demo THEN RAISE EXCEPTION 'The entry changed. Refresh and try again.'; END IF;
  IF EXISTS (SELECT 1 FROM public.owner_time_entries WHERE amends_entry_id = original.id) THEN
    -- Double save guard (Nov 21): a second click on Save finds her change already on file.
    IF private.owner_time_recent_repeat(program.id, uid,
         CASE WHEN mode = 'edit' THEN coalesce(nullif(_change->>'entryDate', '')::date, original.entry_date) ELSE original.entry_date END,
         CASE WHEN mode = 'edit' THEN coalesce(nullif(_change->>'minutes', '')::integer, original.minutes) ELSE original.minutes END,
         CASE WHEN mode = 'edit' THEN btrim(coalesce(_change->>'activity', original.activity)) ELSE original.activity END,
         _change->>'note', original.id) THEN
      RAISE EXCEPTION 'Already saved.';
    END IF;
    RAISE EXCEPTION 'This entry was already updated. Refresh to see the latest version.';
  END IF;

  old_paths := CASE WHEN jsonb_typeof(original.attachment_paths) = 'array' AND jsonb_array_length(original.attachment_paths) > 0 THEN original.attachment_paths
                    WHEN original.attachment_path IS NOT NULL THEN jsonb_build_array(original.attachment_path)
                    ELSE '[]'::jsonb END;
  -- Files are only added: every file she sent before stays with the entry.
  added := coalesce(_change->'addPaths', '[]'::jsonb);
  IF jsonb_typeof(added) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'One of the files could not be recorded. Try again.'; END IF;
  FOR p IN SELECT jsonb_array_elements_text(added) LOOP
    IF p IS NULL OR length(p) NOT BETWEEN 1 AND 400 OR old_paths ? p
       OR left(p, length('owner_participation/' || program.id::text || '/')) <> 'owner_participation/' || program.id::text || '/' THEN
      RAISE EXCEPTION 'One of the files could not be recorded. Try again.';
    END IF;
  END LOOP;
  paths := old_paths || added;
  IF jsonb_array_length(paths) > 10 THEN RAISE EXCEPTION 'Attach at most ten files to one entry.'; END IF;

  IF mode = 'edit' THEN
    act := btrim(coalesce(_change->>'activity', original.activity));
    day := coalesce(nullif(_change->>'entryDate', '')::date, original.entry_date);
    mins := coalesce(nullif(_change->>'minutes', '')::integer, original.minutes);
  ELSE
    act := original.activity; day := original.entry_date; mins := original.minutes;
  END IF;
  note := nullif(btrim(coalesce(_change->>'note', '')), '');
  IF mins IS NULL OR mins NOT BETWEEN 1 AND 1440 THEN RAISE EXCEPTION 'Enter the time you spent, up to 24 hours.'; END IF;
  IF length(coalesce(act, '')) < 3 THEN RAISE EXCEPTION 'What did you do? needs at least 3 characters.'; END IF;
  IF length(act) > 2000 THEN RAISE EXCEPTION 'What did you do? can be up to 2,000 characters.'; END IF;
  IF day IS NULL OR NOT isfinite(day) OR day > private.business_today() THEN RAISE EXCEPTION 'Choose a date no later than today.'; END IF;
  IF note IS NOT NULL AND length(note) > 1000 THEN RAISE EXCEPTION 'Keep your note under 1,000 characters.'; END IF;
  IF original.review_id IS NOT NULL THEN
    SELECT * INTO review FROM public.owner_reviews WHERE id = original.review_id;
    IF FOUND AND review.available_from IS NOT NULL AND day < review.available_from::date THEN
      RAISE EXCEPTION 'Choose a date on or after the day this was sent to you.';
    END IF;
  END IF;

  IF mins IS DISTINCT FROM original.minutes THEN changed := array_append(changed, 'time'); END IF;
  IF day IS DISTINCT FROM original.entry_date THEN changed := array_append(changed, 'date'); END IF;
  IF act IS DISTINCT FROM original.activity THEN changed := array_append(changed, 'description'); END IF;
  IF note IS NOT NULL THEN changed := array_append(changed, 'note'); END IF;
  IF paths IS DISTINCT FROM old_paths THEN changed := array_append(changed, 'files'); END IF;
  IF cardinality(changed) = 0 THEN
    RAISE EXCEPTION '%', CASE WHEN mode = 'add' THEN 'Add a note or a file first.' ELSE 'Nothing changed.' END;
  END IF;

  -- Double save guard (Nov 21): the same date, minutes and description saved in the last 10 minutes
  -- (other than this entry and the versions before it) is already on file.
  IF private.owner_time_recent_repeat(program.id, uid, day, mins, act, note, original.id) THEN
    RAISE EXCEPTION 'Already saved.';
  END IF;
  comments := original.comments;
  IF note IS NOT NULL THEN
    comments := concat_ws(E'\n\n', nullif(comments, ''), 'Added ' || to_char(private.business_today(), 'Mon FMDD') || ': ' || note);
  END IF;
  IF length(coalesce(comments, '')) > 4000 THEN RAISE EXCEPTION 'This entry has too many notes. Start a new entry instead.'; END IF;
  reason := CASE WHEN mode = 'add' THEN 'Homeowner added more' ELSE 'Homeowner edited the entry' END;

  INSERT INTO public.owner_time_entries(program_id, owner_user_id, phase, entry_date, minutes, activity, activity_category, output,
      decision_outcome, materials_reviewed, attachment_path, attachment_paths, comments, review_id, ticket_id, amends_entry_id,
      correction_reason, review_status, attested, is_demo)
  VALUES (original.program_id, original.owner_user_id, original.phase, day, mins, act, original.activity_category, original.output,
      original.decision_outcome, original.materials_reviewed, paths->>0, paths, comments, original.review_id, original.ticket_id, original.id,
      reason, 'submitted', true, original.is_demo)
  RETURNING id INTO new_id;
  INSERT INTO public.owner_time_entry_properties(entry_id, property_id)
    SELECT new_id, property_id FROM public.owner_time_entry_properties WHERE entry_id = original.id ORDER BY property_id;
  SELECT property_id INTO home FROM public.owner_time_entry_properties WHERE entry_id = new_id ORDER BY property_id LIMIT 1;
  UPDATE public.owner_programs SET last_owner_activity_at = now() WHERE id = program.id;
  INSERT INTO public.owner_program_events(program_id, entry_id, review_id, kind, summary, actor_id, previous_value, new_value, reason, detail)
  VALUES (program.id, new_id, original.review_id, 'time_entry', reason || ': ' || act, uid, original.minutes::text, mins::text, reason,
    jsonb_build_object('correctionOf', original.id, 'homeownerUpdate', true, 'changed', to_jsonb(changed),
      'wasReviewed', original.reviewed_at IS NOT NULL, 'attachmentCount', jsonb_array_length(paths),
      'propertyIds', coalesce((SELECT jsonb_agg(property_id ORDER BY property_id) FROM public.owner_time_entry_properties WHERE entry_id = new_id), '[]'::jsonb)));
  label := to_char(day, 'Mon FMDD');
  PERFORM private.record_homeowner_update(program.id, home, 'hours', new_id, 'Hours on ' || label, NULL,
    reason || ' for ' || label || ': ' || left(act, 200),
    CASE WHEN mode = 'add' THEN 'I added more to my hours for ' ELSE 'I updated my hours for ' END || label || ': ' || left(act, 200) || '.');
  RETURN new_id;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'The program or entry is being updated. Refresh and try again.';
END $function$

CREATE OR REPLACE FUNCTION public.respond_owner_approval(_approval_id uuid, _publication_id uuid, _expected_updated_at timestamp with time zone, _approved boolean, _note text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE request public.approvals%ROWTYPE; publication public.owner_approval_publications%ROWTYPE; decided timestamptz;
BEGIN
 IF auth.uid() IS NULL OR _approved IS NULL OR length(coalesce(_note,''))>2000 OR (_approved=false AND length(trim(coalesce(_note,'')))=0) THEN
  RAISE EXCEPTION 'Sign in and provide a valid decision, including a note when requesting changes.';
 END IF;
 -- Do not inspect/lock another recipient's operational source on a guessed id.
 IF NOT EXISTS(SELECT 1 FROM public.approvals a WHERE a.id=_approval_id AND a.approver_id=auth.uid() AND a.approver_role='owner'
  AND a.is_demo=false AND private.owner_approval_program(a) IS NOT NULL) THEN RAISE EXCEPTION 'That approval is not available to this owner account.'; END IF;
 request:=private.lock_owner_approval(_approval_id);
 SELECT * INTO publication FROM public.owner_approval_publications WHERE approval_id=request.id ORDER BY revision DESC LIMIT 1;
 IF publication.id IS NULL OR _publication_id IS DISTINCT FROM publication.id OR _expected_updated_at IS NULL OR request.updated_at IS DISTINCT FROM _expected_updated_at
  OR publication.approval_updated_at IS DISTINCT FROM request.updated_at OR publication.recipient_id IS DISTINCT FROM auth.uid()
  OR publication.program_id IS DISTINCT FROM private.owner_approval_program(request)
  OR publication.owner_record_id IS DISTINCT FROM (SELECT owner_record_id FROM public.owner_programs WHERE id=publication.program_id)
  OR publication.property_id IS DISTINCT FROM request.property_id OR publication.entity_type IS DISTINCT FROM request.entity_type OR publication.entity_id IS DISTINCT FROM request.entity_id THEN
  RAISE EXCEPTION 'A current staff-reviewed summary is required. Review the updated request before responding; your note can be kept.';
 END IF;
 IF request.entity_type IN('work_order','onboarding_task','financial_request') THEN
  decided:=public.record_versioned_owner_response(request.id,auth.uid(),_expected_updated_at,_approved,trim(coalesce(_note,'')));
 ELSE
  decided:=now();
  UPDATE public.approvals SET status=CASE WHEN _approved THEN 'approved' ELSE 'declined' END,decision_note=nullif(trim(_note),''),decided_at=decided WHERE id=request.id;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.owner_approval_receipts r WHERE r.approval_id=request.id AND r.publication_id=publication.id AND r.actor_id=auth.uid()) THEN
  RAISE EXCEPTION 'The exact reviewed decision context could not be retained. No response was saved.';
 END IF;
 -- Work Order delegate already writes its canonical audit. This publication receipt
 -- is additional immutable context; task/finance/generic responses need this audit.
 IF request.entity_type<>'work_order' THEN
  INSERT INTO public.audit_log(actor_id,action,entity_type,entity_id,reason,after_value)
  VALUES(auth.uid(),CASE WHEN _approved THEN 'owner_approval_approved' ELSE 'owner_approval_declined' END,'approval',request.id,nullif(trim(_note),''),
   jsonb_build_object('decided_at',decided,'publication_id',publication.id,'revision',publication.revision));
 END IF;
 RETURN decided;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'The approval context is being updated. Refresh and review it before responding.';
END $function$

CREATE OR REPLACE FUNCTION private.lock_owner_time_program(_program_id uuid, _actor_id uuid, _staff boolean, _new_activity boolean)
 RETURNS owner_programs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE program public.owner_programs; arrived boolean;
BEGIN
 SELECT * INTO program FROM public.owner_programs WHERE id=_program_id FOR UPDATE NOWAIT;
 IF NOT FOUND OR _actor_id IS NULL OR program.archived_at IS NOT NULL OR program.completed_at IS NOT NULL THEN
  RAISE EXCEPTION 'This program is not open for this participation change.';
 END IF;
 SELECT EXISTS(SELECT 1 FROM public.owner_program_properties e WHERE e.program_id=program.id AND e.inclusion_status='included'
   AND e.archived_at IS NULL AND e.is_demo=program.is_demo AND e.closing_confirmed AND e.closing_date IS NOT NULL
   AND e.closing_date<=private.business_today()) INTO arrived;
 IF _new_activity AND NOT _staff THEN
  IF NOT coalesce(private.owner_program_live(program.status), false) THEN
   RAISE EXCEPTION 'This program is not open for this participation change.';
 END IF;

 ELSIF (program.started_on IS NULL OR NOT isfinite(program.started_on)) AND NOT (program.status IN ('draft','waiting_for_closing','ready_for_onboarding') AND arrived)
  OR (_new_activity AND NOT coalesce(private.owner_program_live(program.status), false))
  OR (NOT _new_activity AND NOT (coalesce(private.owner_program_live(program.status), false) OR program.status = 'paused')) THEN
  RAISE EXCEPTION 'This program is not open for this participation change.';
 END IF;
 PERFORM 1 FROM auth.users WHERE id=_actor_id AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=now()) FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'An enabled account is required for participation changes.'; END IF;
 PERFORM 1 FROM public.user_roles WHERE user_id=_actor_id FOR SHARE NOWAIT;
 IF _staff THEN
   IF NOT (coalesce(public.has_role(_actor_id,'admin'),false) OR coalesce(public.has_role(_actor_id,'manager'),false))
   OR (program.is_demo AND NOT coalesce(public.has_role(_actor_id,'admin'),false)) THEN
   RAISE EXCEPTION 'Only an authorized supervisor can review or correct participation.';
  END IF;
 ELSE
  IF NOT coalesce(private.is_program_member(program.id,_actor_id),false)
   OR (program.is_demo AND NOT (_actor_id=auth.uid() AND private.is_synthetic_account()
        AND coalesce(private.demo_owner_link_ok(_actor_id, program.id),false)))
   OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_actor_id AND role::text='owner')
   OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_actor_id AND role::text<>'owner') THEN
    RAISE EXCEPTION 'That participation program is not available to you.';
  END IF;
 END IF;
 PERFORM 1 FROM public.property_owners WHERE id=program.owner_record_id AND active FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'Participation requires an active canonical Owner.'; END IF;
 RETURN program;
END $function$
